package pt.qpetiscos.agenda;
import android.app.*;import android.appwidget.*;import android.app.job.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.widget.RemoteViews;import org.json.*;import java.net.*;import java.io.*;import java.time.*;import java.util.concurrent.*;
public class WidgetAgenda extends AppWidgetProvider {
 static final String BASE="https://kyzwmaydwokbfmiskhcg.supabase.co/rest/v1/events", KEY="sb_publishable_Ko1iv1CWVi693R9_-xwNvg_5auNwzAy";
 static final ExecutorService EXEC=Executors.newSingleThreadExecutor();static void runAsync(Runnable r){EXEC.execute(r);} static void refreshAll(Context c){Context a=c.getApplicationContext();runAsync(()->updateAll(a));}
 static void schedule(Context c){JobScheduler js=c.getSystemService(JobScheduler.class);if(js.getPendingJob(410)==null)js.schedule(new JobInfo.Builder(410,new ComponentName(c,WidgetJob.class)).setPeriodic(15*60*1000).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).build());}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){schedule(c);refreshAll(c);}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);String action=i.getAction();if(!"qp.refresh".equals(action)&&!"qp.toggle".equals(action))return;PendingResult pending=goAsync();Context a=c.getApplicationContext();runAsync(()->{try{if("qp.toggle".equals(action)){JSONObject s=session(a);String id=i.getStringExtra("event");if(id!=null&&id.matches("[a-fA-F0-9-]{36}")){JSONObject body=new JSONObject().put("completed",i.getBooleanExtra("done",false)).put("updated_by",s.getString("device"));request(s,"PATCH","?id=eq."+id+"&user_id=eq."+s.getString("uid")+"&deleted_at=is.null",body);}}}catch(Exception e){android.util.Log.w("QPWidget","Alteração falhou",e);}finally{updateAll(a);pending.finish();}});}
 static JSONObject session(Context c)throws Exception{JSONObject s=new JSONObject(c.getSharedPreferences("widget_session",0).getString("session",""));if(s.isNull("device")||s.optString("device").isEmpty())throw new IOException("Abre a agenda e inicia sessão");return s;}
 static String request(JSONObject s,String method,String query,JSONObject body)throws Exception{HttpURLConnection h=(HttpURLConnection)new URL(BASE+query).openConnection();h.setConnectTimeout(5000);h.setReadTimeout(5000);h.setRequestMethod(method);h.setRequestProperty("apikey",KEY);h.setRequestProperty("Authorization","Bearer "+s.getString("token"));try{if(body!=null){h.setDoOutput(true);h.setRequestProperty("Content-Type","application/json");try(OutputStream o=h.getOutputStream()){o.write(body.toString().getBytes("UTF-8"));}}int code=h.getResponseCode();if(code==401||code==403)throw new IOException("Abre a agenda para renovar a sessão");if(code<200||code>=300)throw new IOException("Erro de sincronização");try(InputStream in=h.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}finally{h.disconnect();}}
 static void updateAll(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);Class<?>[] types={CompactWidget.class,FullWidget.class,TakeawayWidget.class};boolean any=false;for(Class<?> t:types)any|=m.getAppWidgetIds(new ComponentName(c,t)).length>0;if(!any)return;JSONArray rows=new JSONArray();String status="";try{JSONObject s=session(c);rows=new JSONArray(request(s,"GET","?select=id,type,name,event_time,notes,completed&user_id=eq."+s.getString("uid")+"&event_date=eq."+LocalDate.now(ZoneId.of("Europe/Lisbon"))+"&deleted_at=is.null&order=event_time.asc,id.asc",null));}catch(Exception e){status=e instanceof JSONException?"Abre a agenda e inicia sessão":e.getMessage();}for(Class<?> t:types)for(int id:m.getAppWidgetIds(new ComponentName(c,t)))render(c,m,t,id,rows,status);}
 static PendingIntent action(Context c,Class<?> t,int id,String action,String event,boolean done){Intent i=new Intent(c,t).setAction(action).setData(Uri.parse("qp://widget/"+id+"/"+action+"/"+event)).putExtra("event",event).putExtra("done",done);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void render(Context c,AppWidgetManager m,Class<?> t,int id,JSONArray rows,String status){int theme=c.getSharedPreferences("widget_theme",0).getInt("theme"+id,0),fg=theme==1?Color.WHITE:0xff432a19,bg=theme==1?0xff432a19:theme==2?Color.TRANSPARENT:Color.WHITE;RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_agenda);v.setInt(R.id.widget_root,"setBackgroundColor",bg);for(int x:new int[]{R.id.widget_title,R.id.widget_status,R.id.widget_refresh,R.id.widget_settings})v.setTextColor(x,fg);boolean compact=t==CompactWidget.class,take=t==TakeawayWidget.class;v.setTextViewText(R.id.widget_title,take?"Takeaway":compact?"QPetiscos":"Agenda de hoje");int reserve=0,orders=0;for(int k=0;k<rows.length();k++){JSONObject e=rows.optJSONObject(k);if(e==null)continue;if("reserva".equals(e.optString("type")))reserve++;else orders++;}v.setTextViewText(R.id.widget_status,status.isEmpty()?(take?orders+" pedidos":reserve+" reservas · "+orders+" takeaway"):status);v.setOnClickPendingIntent(R.id.widget_refresh,action(c,t,id,"qp.refresh","",false));Intent settings=new Intent(c,WidgetSettings.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);v.setOnClickPendingIntent(R.id.widget_settings,PendingIntent.getActivity(c,id,settings,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.widget_title,open);v.removeAllViews(R.id.widget_rows);int count=0;int height=m.getAppWidgetOptions(id).getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,compact?110:take?110:250);int limit=compact?1:Math.max(1,Math.min(10,(height-55)/45));for(int k=0;k<rows.length()&&count<limit;k++){JSONObject e=rows.optJSONObject(k);if(e==null)continue;boolean res="reserva".equals(e.optString("type")),done=e.optBoolean("completed");if(take&&res||compact&&done)continue;String time=e.optString("event_time");if(time.length()>5)time=time.substring(0,5);RemoteViews row=new RemoteViews(c.getPackageName(),R.layout.widget_row);String notes=e.optString("notes","").replace('\n',' ');row.setTextViewText(R.id.row_text,time+" · "+(res?"Reserva":"Takeaway")+"\n"+e.optString("name")+(notes.isEmpty()?"":"\n"+notes));row.setTextColor(R.id.row_text,done?0xff999999:fg);row.setTextViewText(R.id.row_done,done?"✓":"○");row.setTextColor(R.id.row_done,theme==1?Color.WHITE:0xff936037);row.setOnClickPendingIntent(R.id.row_text,open);row.setOnClickPendingIntent(R.id.row_done,action(c,t,id,"qp.toggle",e.optString("id"),!done));v.addView(R.id.widget_rows,row);count++;}m.updateAppWidget(id,v);}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,android.os.Bundle b){refreshAll(c);}
}
